export type { DeepRecord } from "./locales/types";
import type { DeepRecord } from "./locales/types";
import idID from "./locales/id-ID";
import enUS from "./locales/en-US";

export type SupportedLocale =
  | "id-ID"
  | "en-US"
  | "en-GB"
  | "zh-CN"
  | "zh-TW"
  | "ja-JP"
  | "ko-KR"
  | "ms-MY"
  | "en-SG"
  | "de-DE"
  | "fr-FR"
  | "nl-NL"
  | "es-ES"
  | "it-IT"
  | "hi-IN"
  | "ar-AE"
  | "ar-SA"
  | "en-AU";

export const SUPPORTED_LOCALES: SupportedLocale[] = [
  "id-ID", "en-US", "en-GB", "zh-CN", "zh-TW", "ja-JP",
  "ko-KR", "ms-MY", "en-SG", "de-DE", "fr-FR", "nl-NL",
  "es-ES", "it-IT", "hi-IN", "ar-AE", "ar-SA", "en-AU",
];

export const RTL_LOCALES: string[] = ["ar-AE", "ar-SA"];

// Runtime cache — starts with only the two eagerly-bundled locales.
const _cache: Record<string, DeepRecord> = {
  "id-ID": idID,
  "en-US": enUS,
};

/** Get a locale from cache (sync). Returns undefined if not yet loaded. */
export function getCachedLocale(code: string): DeepRecord | undefined {
  return _cache[code];
}

/** Load a locale asynchronously. Subsequent calls return the cached result. */
export async function loadLocale(code: string): Promise<DeepRecord> {
  if (_cache[code]) return _cache[code];
  const mod = await (async () => {
    switch (code) {
      case "en-GB": return import("./locales/en-GB");
      case "zh-CN": return import("./locales/zh-CN");
      case "zh-TW": return import("./locales/zh-TW");
      case "ja-JP": return import("./locales/ja-JP");
      case "ko-KR": return import("./locales/ko-KR");
      case "ms-MY": return import("./locales/ms-MY");
      case "en-SG": return import("./locales/en-SG");
      case "de-DE": return import("./locales/de-DE");
      case "fr-FR": return import("./locales/fr-FR");
      case "nl-NL": return import("./locales/nl-NL");
      case "es-ES": return import("./locales/es-ES");
      case "it-IT": return import("./locales/it-IT");
      case "hi-IN": return import("./locales/hi-IN");
      case "ar-AE": return import("./locales/ar-AE");
      case "ar-SA": return import("./locales/ar-SA");
      case "en-AU": return import("./locales/en-AU");
      default: return { default: idID };
    }
  })();
  _cache[code] = mod.default;
  return _cache[code];
}

// Note: TRANSLATIONS is exported at the top of this file (the full static object).
// _cache is used internally by loadLocale() for lazy-loaded locales.
